function initStars(){const c=$('flightCanvas'),w=c.clientWidth,h=c.clientHeight;stars=Array.from({length:160},()=>({x:Math.random()*w,y:Math.random()*h,size:Math.random()*1.7+.3,alpha:Math.random()*.7+.2,tw:Math.random()*6.2}));particles=[]}
function drawScene(dt){const c=$('flightCanvas'),ctx=c.getContext('2d'),w=c.clientWidth,h=c.clientHeight;if(!w||!h)return;ctx.clearRect(0,0,w,h);const sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,selectedPlanet.sky);sky.addColorStop(.7,'#102029');sky.addColorStop(1,phase==='landing'?selectedPlanet.surface:'#121d20');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);
// distant stars and a quiet, moving nebula
const neb=ctx.createRadialGradient(w*.78,h*.24,2,w*.78,h*.24,w*.48);neb.addColorStop(0,selectedPlanet.glow+'30');neb.addColorStop(1,'transparent');ctx.fillStyle=neb;ctx.fillRect(0,0,w,h);for(const s of stars){s.tw+=dt*1.5;ctx.globalAlpha=s.alpha*(.75+Math.sin(s.tw)*.25);ctx.fillStyle='#e7f1df';ctx.fillRect(s.x,s.y,s.size,s.size)}ctx.globalAlpha=1;
let planetX=w*.74,planetY=h*.34,rad=Math.min(w,h)*.15;if(phase==='cruise'){rad=Math.min(w*.24,rad+phaseTime*2.7);planetX=w*.73+Math.sin(phaseTime*.27)*w*.04;planetY=h*.38}else if(phase==='landing'){rad=Math.min(w*.76,h*.56,rad+phaseTime*24);planetX=w*.5;planetY=h*.94;}
if(phase!=='launch'&&phase!=='preflight'){ctx.save();ctx.beginPath();ctx.arc(planetX,planetY,rad,0,Math.PI*2);const pg=ctx.createRadialGradient(planetX-rad*.33,planetY-rad*.4,rad*.05,planetX,planetY,rad*1.15);pg.addColorStop(0,selectedPlanet.color);pg.addColorStop(.63,selectedPlanet.surface);pg.addColorStop(1,'#080d10');ctx.fillStyle=pg;ctx.shadowColor=selectedPlanet.glow;ctx.shadowBlur=phase==='landing'?32:15;ctx.fill();ctx.shadowBlur=0;ctx.save();ctx.clip();ctx.globalAlpha=.19;ctx.strokeStyle='#ffdfb6';ctx.lineWidth=Math.max(2,rad*.06);for(let i=-2;i<3;i++){ctx.beginPath();ctx.ellipse(planetX,planetY+rad*i*.33,rad*.98,rad*.21,i*.12,0,Math.PI*2);ctx.stroke()}ctx.globalAlpha=.2;for(let i=0;i<16;i++){const x=planetX+Math.sin(i*42)*rad*.77,y=planetY+Math.cos(i*23)*rad*.7,r=rad*(.025+(i%3)*.018);ctx.fillStyle=i%2?'#2a2923':'#e5c4a0';ctx.beginPath();ctx.ellipse(x,y,r*1.5,r,0,0,Math.PI*2);ctx.fill()}ctx.restore();ctx.restore()}
if(phase==='launch'||phase==='preflight'){const horizon=h*(.84-Math.min(.2,altitude/1000));const ag=ctx.createLinearGradient(0,horizon-90,0,horizon+30);ag.addColorStop(0,'transparent');ag.addColorStop(.6,selectedPlanet.glow+'60');ag.addColorStop(1,selectedPlanet.surface);ctx.fillStyle=ag;ctx.fillRect(0,horizon-90,w,140);ctx.fillStyle='#161d1b';ctx.beginPath();ctx.moveTo(0,horizon+25);for(let x=0;x<=w;x+=w/8)ctx.lineTo(x,horizon+Math.sin(x*.024+elapsed*.15)*9+Math.random()*1);ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.fill()}
// landing terrain and approach lights
if(phase==='landing'){const horizon=h*.78;ctx.fillStyle=selectedPlanet.surface;ctx.beginPath();ctx.moveTo(0,horizon);for(let x=0;x<=w;x+=w/12)ctx.lineTo(x,horizon+Math.sin(x*.019+elapsed)*13);ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.fill();ctx.globalAlpha=.42;ctx.strokeStyle='#e8cc9c';ctx.lineWidth=1;for(let i=0;i<13;i++){const x=(i/12)*w;ctx.beginPath();ctx.moveTo(x,horizon+Math.sin(x*.019+elapsed)*13);ctx.lineTo(w/2+(x-w/2)*1.6,h);ctx.stroke()}ctx.globalAlpha=1;for(let i=0;i<9;i++){const x=(i/8)*w;ctx.fillStyle=i%2?'#ffc77d':'#73e8d2';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=8;ctx.beginPath();ctx.arc(x,horizon+Math.sin(x*.019+elapsed)*13,2.4,0,Math.PI*2);ctx.fill()}ctx.shadowBlur=0}
// engine exhaust sparks
for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.y+=p.v*dt;p.life-=dt*1.3;ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=i%2?'#d4fc57':'#ff9f61';ctx.beginPath();ctx.arc(p.x*w,p.y*h,2+Math.random()*2,0,Math.PI*2);ctx.fill();if(p.life<=0)particles.splice(i,1)}ctx.globalAlpha=1;
// spacecraft, centered on the flight corridor
const sx=w*(.5+steer*.09),sy=phase==='launch'?h*(.62-Math.min(.23,altitude/900)):phase==='landing'?h*(.19+Math.min(.5,(100-altitude)/200)):h*.54;const scale=Math.max(.65,Math.min(1.5,Math.min(w,h)/420));ctx.save();ctx.translate(sx,sy);ctx.scale(scale,scale);ctx.rotate(phase==='cruise'?steer*.09:steer*.06);
if(throttle>3&&phase!=='cruise'){const fl=18+throttle*.36+Math.sin(elapsed*22)*5;const fg=ctx.createLinearGradient(0,20,0,20+fl);fg.addColorStop(0,'#eaf882');fg.addColorStop(.36,'#ffb35e');fg.addColorStop(1,'#ff6542');ctx.fillStyle=fg;ctx.shadowColor='#ffad53';ctx.shadowBlur=15;ctx.beginPath();ctx.moveTo(-7,17);ctx.lineTo(0,18+fl);ctx.lineTo(7,17);ctx.fill();ctx.shadowBlur=0}
// fins and fuselage
ctx.fillStyle='#b8c6b8';ctx.beginPath();ctx.moveTo(-12,10);ctx.lineTo(-23,25);ctx.lineTo(-10,22);ctx.closePath();ctx.fill();ctx.beginPath();ctx.moveTo(12,10);ctx.lineTo(23,25);ctx.lineTo(10,22);ctx.closePath();ctx.fill();const body=ctx.createLinearGradient(-10,0,10,0);body.addColorStop(0,'#77877d');body.addColorStop(.42,'#f1f0dc');body.addColorStop(1,'#89998c');ctx.fillStyle=body;ctx.beginPath();ctx.moveTo(0,-29);ctx.bezierCurveTo(10,-20,11,-8,9,15);ctx.lineTo(7,21);ctx.lineTo(-7,21);ctx.lineTo(-9,15);ctx.bezierCurveTo(-11,-8,-10,-20,0,-29);ctx.fill();ctx.fillStyle='#78998d';ctx.beginPath();ctx.arc(0,-7,4.2,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#d4fc57';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(-8,10);ctx.lineTo(8,10);ctx.stroke();ctx.restore();
}
// Throttle is analog: hold to build thrust, release to coast. Arrow/W/S work on keyboard.
function updateThrottle(dt){const rising=keys[' ']||keys.arrowup||keys.w||touchThrottle;const falling=keys.arrowdown||keys.s;if(rising)setThrottle(throttle+dt*52);else if(falling)setThrottle(throttle-dt*72);else if(phase==='launch')setThrottle(Math.max(0,throttle-dt*5));if(phase==='cruise'&&!rising&&!falling)setThrottle(Math.max(0,throttle-dt*22))}
const originalLoop=loop;
</script>
</body>
</html>

