 function rocketMarkup(r){return `<button class="rocket-card ${r===selectedRocket?'selected':''}" data-id="${r.id}"><div class="rocket-top"><span class="rocket-icon"><svg viewBox="0 0 24 36" fill="none"><path d="M12 2C8 7 7 12 7 21h10c0-9-1-14-5-19Z" fill="currentColor"/><path d="M7 17 2 23v6l5-3m10-9 5 6v6l-5-3" fill="currentColor" opacity=".55"/><path d="M9 29c0 3 1 5 3 6 2-1 3-3 3-6" fill="#ff9f61"/><circle cx="12" cy="13" r="2" fill="#14201a"/></svg></span><span class="rocket-grade">${r.grade}</span></div><div class="rocket-name">${r.name}</div><div class="rocket-desc">${r.desc}</div><div class="rocket-stat"><span>THRUST</span><div class="stat-track"><i style="width:${r.power}%"></i></div><span>${r.power}</span></div></button>`}
 function renderSetup(){ $('destinationGrid').innerHTML=planets.map(planetMarkup).join('');$('rocketGrid').innerHTML=rockets.map(rocketMarkup).join('');updatePreview();document.querySelectorAll('.planet-card').forEach(b=>b.onclick=()=>{selectedPlanet=planets.find(p=>p.id===b.dataset.id);renderSetup()});document.querySelectorAll('.rocket-card').forEach(b=>b.onclick=()=>{selectedRocket=rockets.find(r=>r.id===b.dataset.id);renderSetup()}) }
 function updatePreview(){ $('previewPlanet').style.setProperty('--planet',selectedPlanet.color);$('previewPlanet').style.setProperty('--planetglow',selectedPlanet.glow);$('previewName').textContent=selectedPlanet.name.toUpperCase();$('previewCaption').textContent=`${selectedPlanet.title}  ·  ${selectedPlanet.distance}`;$('previewTime').textContent=selectedPlanet.time;$('previewDifficulty').textContent='● '.repeat(selectedPlanet.difficulty)+'○ '.repeat(3-selectedPlanet.difficulty);$('previewGravity').textContent=selectedPlanet.gravity }
 renderSetup();
-function enterGame(){ $('resultScreen').classList.remove('show');$('setupScreen').classList.add('hidden');$('gameScreen').classList.add('active');$('missionDestination').textContent=selectedPlanet.name.toUpperCase();$('hudCraft').textContent=selectedRocket.name;$('phaseName').textContent='Preflight checks';phase='preflight';elapsed=0;phaseTime=0;throttle=0;steer=0;touchThrottle=false;keys={};altitude=0;speed=0;fuel=100;hull=100;oxygen=100;score=0;toastShown=false;setThrottle(0);$('targetLabel').innerHTML='ORBITAL INSERTION<div class="target-value" id="targetValue">200 km</div>';$('speedLabel').textContent='VELOCITY';$('controlGuide').innerHTML='<b>SPACE / ↑</b> THROTTLE &nbsp; <b>← →</b> STEER<br>RELEASE TO CUT ENGINE';updateTimeline();setObjective('Waiting for launch window.','Run all systems checks before ignition.');setToast('SYSTEMS CHECK','PREPARING LAUNCH WINDOW...');resizeCanvas();initStars();cancelAnimationFrame(raf);last=performance.now();raf=requestAnimationFrame(loop);setTimeout(()=>{if(phase==='preflight'){setToast('ALL SYSTEMS NOMINAL','HOLD THROTTLE TO IGNITE')}},1800)}
+function enterGame(){ $('resultScreen').classList.remove('show');$('setupScreen').classList.add('hidden');$('gameScreen').classList.add('active');window.scrollTo(0,0);$('missionDestination').textContent=selectedPlanet.name.toUpperCase();$('hudCraft').textContent=selectedRocket.name;$('phaseName').textContent='Preflight checks';phase='preflight';elapsed=0;phaseTime=0;throttle=0;steer=0;touchThrottle=false;keys={};altitude=0;speed=0;fuel=100;hull=100;oxygen=100;score=0;toastShown=false;setThrottle(0);$('targetLabel').innerHTML='ORBITAL INSERTION<div class="target-value" id="targetValue">200 km</div>';$('speedLabel').textContent='VELOCITY';$('controlGuide').innerHTML='<b>SPACE / ↑</b> THROTTLE &nbsp; <b>← →</b> STEER<br>RELEASE TO CUT ENGINE';updateTimeline();setObjective('Waiting for launch window.','Run all systems checks before ignition.');setToast('SYSTEMS CHECK','PREPARING LAUNCH WINDOW...');resizeCanvas();initStars();cancelAnimationFrame(raf);last=performance.now();raf=requestAnimationFrame(loop);setTimeout(()=>{if(phase==='preflight'){setToast('ALL SYSTEMS NOMINAL','HOLD THROTTLE TO IGNITE')}},1800)}
 $('launchButton').onclick=enterGame;
 function toggleSound(){muted=!muted;$('soundToggle').textContent=muted?'♫  SOUND OFF':'♫  SOUND ON';$('flightSound').textContent=muted?'♫ SOUND OFF':'♫ SOUND ON'}$('soundToggle').onclick=toggleSound;$('flightSound').onclick=toggleSound;
 function phases(){return [{id:'preflight',label:'Preflight checks'},{id:'launch',label:'Launch & ascent'},{id:'cruise',label:'Deep-space cruise'},{id:'landing',label:'Atmospheric entry'},{id:'complete',label:'Touchdown'}]}
 function updateTimeline(){const order=['preflight','launch','cruise','landing','complete'];const idx=order.indexOf(phase);$('phaseList').innerHTML=phases().map((p,i)=>`<div class="phase-step ${i===idx?'active':i<idx?'done':''}"><i>${i<idx?'✓':String(i+1).padStart(2,'0')}</i>${p.label}</div>`).join('')}
